INSERT INTO `page_schemas` (`id`, `page_key`, `page_title`, `schema_name`, `schema_type`, `schema_data`, `status`, `created_at`, `updated_at`) VALUES (44, 'service-ugc-testimonial-videos-company', 'Ugc Testimonial Videos Service', 'Ugc Testimonial Videos Service BreadcrumbList Schema', 'BreadcrumbList', '{\n    \"@context\": \"https://schema.org\",\n    \"@type\": \"BreadcrumbList\",\n    \"@id\": \"https://myugcvideo.in/services/ugc-testimonial-videos-company#breadcrumb\",\n    \"itemListElement\": [\n        {\n            \"@type\": \"ListItem\",\n            \"position\": 1,\n            \"name\": \"Home\",\n            \"item\": \"https://myugcvideo.in\"\n        },\n        {\n            \"@type\": \"ListItem\",\n            \"position\": 2,\n            \"name\": \"Services\",\n            \"item\": \"https://myugcvideo.in/services\"\n        },\n        {\n            \"@type\": \"ListItem\",\n            \"position\": 3,\n            \"name\": \"Ugc Testimonial Videos Service\",\n            \"item\": \"https://myugcvideo.in/services/ugc-testimonial-videos-company\"\n        }\n    ]\n}', 'published', '2026-11-05 15:33:54', '2026-11-13 14:14:39');
INSERT INTO `page_schemas` (`id`, `page_key`, `page_title`, `schema_name`, `schema_type`, `schema_data`, `status`, `created_at`, `updated_at`) VALUES (46, 'service-ugc-testimonial-videos-company', 'Ugc Testimonial Videos Service', 'Ugc Testimonial Videos Service FAQPage Schema', 'FAQPage', '{\n    \"@context\": \"https://schema.org\",\n    \"@type\": \"FAQPage\",\n    \"@id\": \"https://myugcvideo.in/services/ugc-testimonial-videos-company#faq\",\n    \"mainEntity\": [\n        {\n            \"@type\": \"Question\",\n            \"name\": \"How are UGC testimonial videos different from product reviews?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"A review is a first-hand opinion about the product. A testimonial tells a customer\'s story: the problem,\\n                the doubt and what changed. Both build trust, but testimonials lean more on emotion.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"Can we tailor testimonials to answer our biggest buyer objections?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Yes. Share the objections in the brief and we\'ll build them into the story for you to approve.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"Can we use these in paid social ads?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Yes. Every video comes with ad rights, and the details are in your agreement.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"Where is the best place to use testimonial videos?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Usually near the add-to-cart button on product pages, in retargeting ads and in cart recovery emails.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"How long does a testimonial package take?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Usually 7 to 12 business days. A big package or slow feedback can add some time.\"\n            }\n        }\n    ]\n}', 'published', '2026-11-05 15:33:54', '2026-11-13 14:14:39');
