INSERT INTO `page_schemas` (`id`, `page_key`, `page_title`, `schema_name`, `schema_type`, `schema_data`, `status`, `created_at`, `updated_at`) VALUES (48, 'service-ugc-unboxing-videos-company', 'Ugc Unboxing Videos Service', 'Ugc Unboxing Videos Service BreadcrumbList Schema', 'BreadcrumbList', '{\n    \"@context\": \"https://schema.org\",\n    \"@type\": \"BreadcrumbList\",\n    \"@id\": \"https://myugcvideo.in/services/ugc-unboxing-videos-company#breadcrumb\",\n    \"itemListElement\": [\n        {\n            \"@type\": \"ListItem\",\n            \"position\": 1,\n            \"name\": \"Home\",\n            \"item\": \"https://myugcvideo.in\"\n        },\n        {\n            \"@type\": \"ListItem\",\n            \"position\": 2,\n            \"name\": \"Services\",\n            \"item\": \"https://myugcvideo.in/services\"\n        },\n        {\n            \"@type\": \"ListItem\",\n            \"position\": 3,\n            \"name\": \"Ugc Unboxing Videos Service\",\n            \"item\": \"https://myugcvideo.in/services/ugc-unboxing-videos-company\"\n        }\n    ]\n}', 'published', '2026-11-05 15:33:54', '2026-11-13 14:14:39');
INSERT INTO `page_schemas` (`id`, `page_key`, `page_title`, `schema_name`, `schema_type`, `schema_data`, `status`, `created_at`, `updated_at`) VALUES (50, 'service-ugc-unboxing-videos-company', 'Ugc Unboxing Videos Service', 'Ugc Unboxing Videos Service FAQPage Schema', 'FAQPage', '{\n    \"@context\": \"https://schema.org\",\n    \"@type\": \"FAQPage\",\n    \"@id\": \"https://myugcvideo.in/services/ugc-unboxing-videos-company#faq\",\n    \"mainEntity\": [\n        {\n            \"@type\": \"Question\",\n            \"name\": \"Why do UGC unboxing videos work so well for e-commerce brands?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Buyers can\'t hold the product before they order. Watching someone else open it is the next best thing,\\n                and it shows them what will land at their door.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"Should we send special PR packaging or standard customer packaging?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Standard customer packaging is usually better, because it shows buyers what they\'ll actually receive. If\\n                you\'d like PR packaging, say so in the brief.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"Do you capture audio for ASMR-style unboxings?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Yes. Clear audio is part of every shoot, and ASMR is one of our formats.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"Can creators demonstrate the product after unboxing it?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Yes. Add it to the brief and we\'ll write it into the script for you to approve.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"How long does an unboxing package take?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Usually 7 to 12 business days. A big package or slow feedback can add some time.\"\n            }\n        }\n    ]\n}', 'published', '2026-11-05 15:33:54', '2026-11-13 14:14:39');
