INSERT INTO `page_schemas` (`id`, `page_key`, `page_title`, `schema_name`, `schema_type`, `schema_data`, `status`, `created_at`, `updated_at`) VALUES (54, 'service-ugc-video-ads-company', 'Ugc Video Ads Service', 'Ugc Video Ads Service FAQPage Schema', 'FAQPage', '{\n    \"@context\": \"https://schema.org\",\n    \"@type\": \"FAQPage\",\n    \"@id\": \"https://myugcvideo.in/services/ugc-video-ads-company#faq\",\n    \"mainEntity\": [\n        {\n            \"@type\": \"Question\",\n            \"name\": \"How do UGC video ads differ from regular organic UGC?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Organic UGC is content you post like normal. An ad is made for paid media, so it needs a strong start,\\n                one clear message, and something that tells people what to do next. We also make a few versions so you\\n                can test which one works.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"How many hook variations do you provide with each ad?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Usually a few per video. Want more? Put it in your brief and we\\u2019ll send you a quote.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"Do you design ads for Meta and TikTok specifically?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Yes. We set the size, captions and text position for each platform. What works on TikTok doesn\\u2019t always\\n                work on YouTube Shorts.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"Can we run these videos as Spark Ads or whitelisted creator ads?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"It depends on the creator saying yes and on what your agreement covers.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"What is the recommended turnaround time for new ad packs?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Usually 7 to 12 business days. If the pack is big or feedback comes late, UGC video ad turnaround can\\n                take longer.\"\n            }\n        }\n    ]\n}', 'published', '2026-11-05 15:33:54', '2026-11-13 14:14:39');
