INSERT INTO `page_schemas` (`id`, `page_key`, `page_title`, `schema_name`, `schema_type`, `schema_data`, `status`, `created_at`, `updated_at`) VALUES (58, 'service-ugc-video-creation-services-company', 'Ugc Video Creation Services Service', 'Ugc Video Creation Services Service FAQPage Schema', 'FAQPage', '{\n    \"@context\": \"https://schema.org\",\n    \"@type\": \"FAQPage\",\n    \"@id\": \"https://myugcvideo.in/services/ugc-video-creation-services-company#faq\",\n    \"mainEntity\": [\n        {\n            \"@type\": \"Question\",\n            \"name\": \"What is included in UGC video creation services?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"We find the creator, write the script, manage the shoot and edit the video. You get final files with\\n                captions, in the sizes you need.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"How do you choose and vet creators for our brand?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"We start from your product and your buyers. Then we shortlist creators whose style and past videos\\n                seem like a good fit. If you want to hire UGC creators from a specific niche or city, tell us in the\\n                brief.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"Can our team review and approve scripts before filming starts?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Yes. Nobody films until you\\u2019ve approved the script.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"What commercial usage rights are included with the videos?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"You can use them in your ads and marketing. The platforms and the duration are written in your\\n                agreement, so please read it before you sign.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"What is the standard turnaround time for final delivery?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Usually 7 to 12 business days. A big batch or slow feedback can add some time to the UGC video\\n                turnaround.\"\n            }\n        }\n    ]\n}', 'published', '2026-11-05 15:33:54', '2026-11-13 14:14:39');
INSERT INTO `page_schemas` (`id`, `page_key`, `page_title`, `schema_name`, `schema_type`, `schema_data`, `status`, `created_at`, `updated_at`) VALUES (59, 'service-ugc-video-editing-service-company', 'Ugc Video Editing Service Service', 'Referenced Organization', 'Organization', '{\n    \"@context\": \"https://schema.org\",\n    \"@type\": \"Organization\",\n    \"@id\": \"https://myugcvideo.in/#organization\",\n    \"name\": \"MY UGC VIDEO\",\n    \"url\": \"https://myugcvideo.in\",\n    \"logo\": {\n        \"@type\": \"ImageObject\",\n        \"@id\": \"https://myugcvideo.in/#logo\",\n        \"url\": \"https://myugcvideo.in/images/hero/hero-creator.jpg\",\n        \"caption\": \"MY UGC VIDEO Studio Logo\"\n    },\n    \"image\": \"https://myugcvideo.in/images/hero/hero-ugc-production.jpg\",\n    \"description\": \"Premier performance-driven UGC video production studio and creator network connecting brands with authentic creator-led video content.\",\n    \"email\": \"hello@myugcvideo.in\",\n    \"sameAs\": [\n        \"https://instagram.com\",\n        \"https://linkedin.com\"\n    ],\n    \"contactPoint\": [\n        {\n            \"@type\": \"ContactPoint\",\n            \"contactType\": \"customer service\",\n            \"email\": \"hello@myugcvideo.in\",\n            \"availableLanguage\": [\n                \"English\",\n                \"Hindi\"\n            ]\n        }\n    ],\n    \"areaServed\": [\n        {\n            \"@type\": \"Country\",\n            \"name\": \"India\"\n        }\n    ]\n}', 'published', '2026-11-05 15:33:54', '2026-11-13 14:14:39');
