INSERT INTO `page_schemas` (`id`, `page_key`, `page_title`, `schema_name`, `schema_type`, `schema_data`, `status`, `created_at`, `updated_at`) VALUES (62, 'service-ugc-video-editing-service-company', 'Ugc Video Editing Service Service', 'Ugc Video Editing Service Service FAQPage Schema', 'FAQPage', '{\n    \"@context\": \"https://schema.org\",\n    \"@type\": \"FAQPage\",\n    \"@id\": \"https://myugcvideo.in/services/ugc-video-editing-company#faq\",\n    \"mainEntity\": [\n        {\n            \"@type\": \"Question\",\n            \"name\": \"Can we send footage from our own creators or customers?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Yes, absolutely. Upload whatever you have and our editors will audit it first.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"How many hook variations can you make from one shoot?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"It depends on the footage. We\'ll confirm the number once we\'ve reviewed your clips.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"Do you provide music licensing?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Yes, all music and effects we use are commercially licensed.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"What aspect ratios do you deliver?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"9:16, 4:5, 1:1 and 16:9.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"What\'s the turnaround for a UGC video editing service order?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Standard delivery is 48 hours, with one revision round included.\"\n            }\n        }\n    ]\n}', 'published', '2026-11-05 15:33:54', '2026-11-13 14:14:39');
