INSERT INTO `page_schemas` (`id`, `page_key`, `page_title`, `schema_name`, `schema_type`, `schema_data`, `status`, `created_at`, `updated_at`) VALUES (66, 'service-ugc-video-company-in-delhi-company', 'Ugc Video In Delhi Service', 'Ugc Video In Delhi Service FAQPage Schema', 'FAQPage', '{\n    \"@context\": \"https://schema.org\",\n    \"@type\": \"FAQPage\",\n    \"@id\": \"https://myugcvideo.in/services/ugc-video-company-in-delhi-company#faq\",\n    \"mainEntity\": [\n        {\n            \"@type\": \"Question\",\n            \"name\": \"Where are your creators based within Delhi NCR?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"All over the region: Delhi, Gurgaon, Noida and nearby areas.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"Can our brand team visit the studio during production?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Yes. Tell us when you\'d like to come and we\'ll plan it around the shoot.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"How quickly can a UGC video company in Delhi turn content around for us?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Filming can be done in about 48 hours, since there\'s no sample shipping delay. Editing and revisions\\n                come after that, and we\'ll share the dates once we have your brief.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"Do you produce content in Hindi and English?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Yes, in Hindi, Hinglish and English.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"Can you handle product returns after filming?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Tell us in your brief if you want the sample back and we\'ll arrange it.\"\n            }\n        }\n    ]\n}', 'published', '2026-11-05 15:33:54', '2026-11-13 14:14:39');
